@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + BirthDate : date
}

class Account {
  + AccountNumber : int
}

class BusinessAccount extends Account {
  + CompanyName : string
  + MonthlyFee : float
}

class PersonalAccount extends Account {}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage extends Page {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "0..1" Account
Account "1" -- "*" Page
PersonalAccount "0..1" -- "*" Page : granted privileges to

@enduml

